contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function. Takes an arbitrary deposit amount to send to c.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // Make a deposit if requested. This is a top-level state-changing call on c.
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        // Observe prior values via public surface
        uint256 priorRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBal = address(c).balance;

        // Call withdraw and capture whether it reverted; this is a top-level state-changing call via try/catch
        bool didRevert;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // Observe after-values
        uint256 recordedAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBal = address(c).balance;

        // General rule: if withdraw did not revert then recorded balance is zero and contract balance decreased by priorRecorded
        assert(didRevert || (recordedAfter == 0 && beforeContractBal >= priorRecorded && afterContractBal + priorRecorded == beforeContractBal));
    }

    // Allow receiving ETH so this test contract can send deposits and receive funds on successful withdraw
    receive() external payable {}
}

